import {categories,models,shops,model,shop,money,regions,shipping} from './data.js';
import {db,tx,uid,clone,currentOffer} from './store.js';
import {compatibility} from './builds.js';

const SHOP_ID='BP';
const qs=new URLSearchParams(location.search);
const page=location.pathname.split('/').pop().replace('.html','')||'dashboard';
const esc=v=>String(v??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmtDate=v=>new Date(v).toLocaleString('vi-VN',{dateStyle:'short',timeStyle:'short'});
const link=(name,p={})=>name+'.html'+(Object.keys(p).length?'?'+new URLSearchParams(p):'');
const statusClass=s=>/Đã|Hoàn tất|Thành công|Đủ|Khả dụng/.test(s)?'status--ok':/Chờ|Cần|Sắp|Thấp|Hết hạn/.test(s)?'status--warn':/Từ chối|Hủy|Không tương thích|Thất bại/.test(s)?'status--bad':'status--info';
const badge=s=>'<span class="status '+statusClass(s)+'">'+esc(s)+'</span>';
const btn=(label,action,id='',kind='secondary')=>'<button type="button" class="btn btn--'+kind+'" data-action="'+action+'"'+(id?' data-id="'+esc(id)+'"':'')+'>'+esc(label)+'</button>';
const panel=(title,body,extra='')=>'<section class="panel panel--padded">'+(title?'<div class="panel__head"><div><h2 style="font-size:var(--text-xl)">'+esc(title)+'</h2>'+extra+'</div></div>':'')+body+'</section>';

function seed(){
 tx(s=>{
  s.shopMeta||={messages:{},packing:{},inventoryLog:[]};
  if(s.overrides['BP-GPU-4060']===undefined)s.overrides['BP-GPU-4060']={stock:2};
  const userId='USER-DEMO-MINH';
  if(!s.users.some(u=>u.id===userId))s.users.push({id:userId,name:'Nguyễn Minh',email:'minh.demo@pcmatch.local',phone:'0900000128'});
  const demo=[
   {id:'BR-260916-018',userId,version:1,status:'open',purpose:'Gaming 2K + lập trình',budget:20000000,scope:'CPU, mainboard, RAM, GPU, SSD, PSU, case',owned:'Đã có màn hình 2K, bàn phím và chuột',region:'HCM',assembly:true,accessories:'no',deadline:'2026-10-01'},
   {id:'BR-260924-021',userId,version:1,status:'open',purpose:'PC học tập và đồ họa cơ bản',budget:18000000,scope:'CPU, mainboard, RAM, GPU, SSD, PSU, case',owned:'Không có linh kiện',region:'HCM',assembly:true,accessories:'no',deadline:'2026-10-03'},
   {id:'BR-260924-022',userId,version:1,status:'open',purpose:'Nâng cấp máy làm việc',budget:12000000,scope:'GPU, SSD, PSU',owned:'Đã có CPU Ryzen 5 7600, mainboard B650M, RAM DDR5 và case mATX',region:'HN',assembly:false,accessories:'no',deadline:'2026-09-29'}
  ];
  for(const r of demo)if(!s.requests.some(x=>x.id===r.id))s.requests.push(r);
  s.shopMeta.messages['BR-260916-018']||=[
   {author:'Nguyễn Minh',role:'buyer',text:'Mình ưu tiên case thoáng, không cần RGB. Tổng vẫn giữ dưới 20 triệu giúp mình nhé.',at:Date.now()-35*60000},
   {author:'BuildPro Sài Gòn',role:'shop',text:'Shop đã nhận yêu cầu. Mình sẽ kiểm tra lại case và nguồn trước khi gửi bản sửa.',at:Date.now()-28*60000}
  ];
  const req=s.requests.find(x=>x.id==='BR-260916-018');
  if(!s.proposals.some(p=>p.id==='PR-BP-DEMO-001')){
   const mids=['CPU-12400','MB-B660','RAM-C16','GPU-4060','SSD-MP44','PSU-550','CASE-MINI'];
   s.proposals.push({id:'PR-BP-DEMO-001',userId:req.userId,requestId:req.id,requestVersion:req.version,version:1,shopId:SHOP_ID,status:'Cần sửa',expires:Date.now()+18*3600000,items:mids.map(mid=>{const o=currentOffer(SHOP_ID+'-'+mid);return {offerId:o.id,qty:1,price:o.price,warranty:o.warranty};}),fee:65000,assembly:150000,feedback:[{version:1,text:'Đổi case thoáng hơn nhưng giữ tổng dưới 20 triệu.',at:Date.now()-20*60000}]});
  }
  if(!s.orders.some(o=>o.id==='PCM-260916-014')){
   const items=['CPU-7600','MB-B650','SSD-SN770'].map(mid=>{const o=currentOffer(SHOP_ID+'-'+mid),m=model(mid);return {id:uid('OI'),offerId:o.id,modelId:m.id,name:m.name,qty:1,price:o.price,warranty:o.warranty,serial:'',serials:[],policy:'Tiếp nhận tại BuildPro Sài Gòn; chính sách snapshot demo.'};});
   const subtotal=items.reduce((a,i)=>a+i.price,0),discount=200000,fee=65000,total=subtotal-discount+fee;
   s.orders.push({id:'PCM-260916-014',intentId:'DEMO-SHOP',userId,at:Date.now()-42*60000,proposalId:null,requestId:null,voucher:null,address:{name:'Nguyễn Minh',phone:'0900000128',detail:'72 Nguyễn Thị Minh Khai, Phường Xuân Hòa',region:'HCM'},payment:'paid',paymentId:'PAY-DEMO-771',total,subtotal,fee,discount,assembly:0,suborders:[{id:'SUB-BP-002',shopId:SHOP_ID,status:'Chờ shop xác nhận',shippingStatus:'Chưa tạo vận đơn',subtotal,fee,deliveryService:'standard',discount,assembly:0,total,timeline:[{at:Date.now()-42*60000,text:'Thanh toán demo thành công; chờ shop xác nhận'}],items}]});
  }
 });
}
seed();

const shopInfo=shop(SHOP_ID);
const bpOffers=()=>models.map(m=>currentOffer(SHOP_ID+'-'+m.id)).filter(Boolean);
const requests=()=>db().requests.filter(r=>r.status==='open'&&new Date(r.deadline+'T23:59:59')>new Date());
const proposals=()=>db().proposals.filter(p=>p.shopId===SHOP_ID);
const suborders=()=>db().orders.flatMap(o=>o.suborders.filter(s=>s.shopId===SHOP_ID).map(s=>({order:o,sub:s})));
const buyerName=r=>db().users.find(u=>u.id===r.userId)?.name||'Người mua';
const proposalTotal=p=>p.items.reduce((sum,i)=>sum+i.price*i.qty,0)+(p.fee||0)+(p.assembly||0);
const reservedFor=offerId=>suborders().filter(({sub})=>!['Đã hủy','Hoàn tất'].includes(sub.status)).reduce((sum,{sub})=>sum+sub.items.filter(i=>i.offerId===offerId).reduce((a,i)=>a+i.qty,0),0);
const activeForRequest=(r)=>proposals().filter(p=>p.requestId===r.id&&p.requestVersion===r.version&&!['Đã rút','Đã thay thế'].includes(p.status));

function sidebar(){
 const item=(file,label,count='')=>'<a href="'+file+'.html" '+(page===file?'aria-current="page"':'')+'>'+label+(count?'<span class="sidebar__count">'+count+'</span>':'')+'</a>';
 return '<aside class="shop-sidebar"><div class="shop-sidebar__brand"><strong>'+esc(shopInfo.name)+'</strong><small>Shop đã xác minh · Chủ shop</small></div><nav><p class="sidebar__group">Vận hành</p>'+item('dashboard','Tổng quan')+item('offers','Tin bán',bpOffers().filter(o=>o.active).length)+item('inventory','Kho',bpOffers().filter(o=>o.stock-reservedFor(o.id)<=2).length+' thấp')+'<p class="sidebar__group">Công việc</p>'+item('build-requests','Yêu cầu Build',requests().length)+item('proposal','Proposal',proposals().filter(p=>['Cần sửa','Đã gửi'].includes(p.status)).length)+item('order','Đơn hàng',suborders().filter(x=>!['Hoàn tất','Đã hủy'].includes(x.sub.status)).length)+item('fulfillment','Giao hàng')+'<p class="sidebar__group">Mở rộng</p><a href="dashboard.html?notice=aftersale" data-disabled-link>Hậu mãi</a><a href="dashboard.html?notice=settlement" data-disabled-link>Đối soát</a></nav></aside>';
}
function shell(content,title='Cổng Shop'){
 document.body.className='shop-app';
 document.body.innerHTML='<a class="skip-link" href="#main">Bỏ qua điều hướng</a><div class="service-bar">'+esc(shopInfo.name)+' · Prototype vận hành shop</div><header class="topbar"><div class="container topbar__inner" style="max-width:none"><button class="menu-toggle" type="button" data-sidebar-toggle aria-expanded="false" aria-label="Mở sidebar"><span></span></button><a class="logo" href="dashboard.html"><i class="logo__mark"></i><span>PC</span><span>Match Shop</span></a><label class="search shop-top-search"><span class="sr-only">Tìm trong shop</span><input id="shop-global-search" placeholder="Tìm request, proposal, offer hoặc đơn"><i class="search__glyph"></i></label><nav class="nav-links"><a href="../buyer/home.html">Mở phía người mua</a><a href="dashboard.html">'+esc(shopInfo.name)+'</a></nav></div></header><div class="shop-shell">'+sidebar()+'<main class="shop-main" id="main"><nav class="breadcrumb"><a href="dashboard.html">Cổng Shop</a><span>'+esc(title)+'</span></nav>'+content+'</main></div><div id="shop-toast" class="shop-toast" hidden role="status"></div>';
}
const head=(title,desc,actions='')=>'<div class="page-head"><div><h1>'+esc(title)+'</h1><p>'+desc+'</p></div><div class="cluster">'+actions+'</div></div>';
function toast(msg){const el=document.querySelector('#shop-toast');el.textContent=msg;el.hidden=false;clearTimeout(window.__shopToast);window.__shopToast=setTimeout(()=>el.hidden=true,2600);}

function dashboard(){
 const openOrders=suborders().filter(x=>!['Hoàn tất','Đã hủy'].includes(x.sub.status));
 const low=bpOffers().filter(o=>o.active&&o.stock-reservedFor(o.id)<=2);
 const waiting=proposals().filter(p=>p.status==='Cần sửa');
 const tasks=[
  ...(openOrders.slice(0,1).map(({sub})=>'<a class="task-row" href="'+link('order',{sub:sub.id})+'"><div><strong>Xác nhận '+esc(sub.id)+'</strong><small>'+sub.items.length+' item · thanh toán đã xác minh</small></div>'+badge(sub.status)+'</a>')),
  ...(waiting.slice(0,1).map(p=>'<a class="task-row" href="'+link('proposal',{id:p.id})+'"><div><strong>Proposal '+esc(p.requestId)+' cần chỉnh sửa</strong><small>'+(p.feedback?.at(-1)?.text||'Người mua yêu cầu cập nhật báo giá')+'</small></div>'+badge('Cần sửa')+'</a>')),
  ...(low.slice(0,1).map(o=>'<a class="task-row" href="'+link('inventory',{offer:o.id})+'"><div><strong>'+esc(o.id)+' còn '+Math.max(0,o.stock-reservedFor(o.id))+' khả dụng</strong><small>Tồn '+o.stock+' · giữ '+reservedFor(o.id)+'</small></div>'+badge('Tồn thấp')+'</a>'))
 ].join('');
 shell(head('Hôm nay cần xử lý gì?','Dữ liệu demo của BuildPro Sài Gòn; ưu tiên theo trạng thái và rủi ro.','<a class="btn btn--secondary" href="offers.html">Quản lý tin bán</a><a class="btn btn--primary" href="build-requests.html">Xem Build Request</a>')+'<div class="shop-kpis"><article class="panel shop-kpi"><span class="metric-label">Đơn cần xử lý</span><strong class="metric-value">'+openOrders.length+'<small> đơn con</small></strong><p>Xác nhận, chuẩn bị hoặc bàn giao.</p></article><article class="panel shop-kpi"><span class="metric-label">Proposal cần phản hồi</span><strong class="metric-value">'+waiting.length+'<small> bản</small></strong><p>Revision giữ lịch sử, không sửa âm thầm.</p></article><article class="panel shop-kpi"><span class="metric-label">Tồn thấp</span><strong class="metric-value">'+low.length+'<small> offer</small></strong><p>Tồn khả dụng = thực tế − đang giữ.</p></article><article class="panel shop-kpi"><span class="metric-label">Request đang mở</span><strong class="metric-value">'+requests().length+'<small> nhu cầu</small></strong><p>Lọc trước khi tốn thời gian lập proposal.</p></article></div><div class="shop-grid"><section class="panel panel--padded"><div class="panel__head"><div><h2 style="font-size:var(--text-xl)">Hàng chờ ưu tiên</h2><p>Những việc nên xử lý tiếp theo.</p></div></div><div class="task-list">'+(tasks||'<p>Không có việc khẩn cấp.</p>')+'</div></section>'+panel('Thao tác nhanh','<div class="stack"><a class="btn btn--secondary" href="offers.html">Tạo / sửa tin bán</a><a class="btn btn--secondary" href="inventory.html">Điều chỉnh tồn kho</a><a class="btn btn--secondary" href="build-requests.html">Tìm request phù hợp</a><a class="btn btn--secondary" href="proposal-builder.html">Tạo proposal</a></div><p class="shop-mini">MVP dùng filter và request có cấu trúc; không cần AI matching.</p>')+'</div>','Tổng quan');
}

function offersPage(){
 const q=(qs.get('q')||'').toLowerCase(),cat=qs.get('category')||'',active=qs.get('active')||'';
 const rows=bpOffers().filter(o=>{const m=model(o.modelId);return (!q||[m.name,m.brand,o.id].join(' ').toLowerCase().includes(q))&&(!cat||m.category===cat)&&(!active||String(Number(o.active))===active);});
 shell(head('Quản lý tin bán','Shop quản lý offer, giá và bảo hành; model kỹ thuật chuẩn không được sửa.','<a class="btn btn--primary" href="../buyer/search.html">Tra model chuẩn</a>')+'<form class="shop-toolbar--compact shop-toolbar" data-form="offer-filter"><label class="field"><span>Tìm offer / model</span><input name="q" value="'+esc(q)+'" placeholder="Ryzen, SSD, BP-CPU..."></label><label class="field"><span>Danh mục</span><select name="category"><option value="">Tất cả</option>'+Object.entries(categories).map(([k,v])=>'<option value="'+k+'" '+(cat===k?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label><label class="field"><span>Trạng thái</span><select name="active"><option value="">Tất cả</option><option value="1" '+(active==='1'?'selected':'')+'>Đang bán</option><option value="0" '+(active==='0'?'selected':'')+'>Tạm ẩn</option></select></label><button class="btn btn--secondary">Lọc</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Offer</th><th>Model chuẩn</th><th>Giá</th><th>Bảo hành</th><th>Tồn</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>'+rows.map(o=>{const m=model(o.modelId);return '<tr><td><strong>'+esc(o.id)+'</strong><small>'+esc(categories[m.category])+'</small></td><td><strong>'+esc(m.name)+'</strong><small>'+esc(m.brand)+'</small></td><td>'+money(o.price)+'</td><td>'+o.warranty+' tháng</td><td>'+o.stock+' thực tế</td><td>'+badge(o.active?'Đang bán':'Tạm ẩn')+'</td><td><div class="shop-table-actions">'+btn('Sửa giá','offer-edit',o.id)+btn(o.active?'Ẩn tin':'Mở bán','offer-toggle',o.id)+'</div></td></tr>';}).join('')+'</tbody></table></div>','Tin bán');
}

function inventoryPage(){
 const selected=qs.get('offer');
 const rows=bpOffers().sort((a,b)=>(a.stock-reservedFor(a.id))-(b.stock-reservedFor(b.id)));
 shell(head('Quản lý kho','Theo dõi tồn thực tế, lượng đang giữ và khả dụng. Điều chỉnh tồn không được thấp hơn lượng đã giữ.','<a class="btn btn--secondary" href="offers.html">Mở tin bán</a>')+'<div class="table-wrap"><table class="data-table"><thead><tr><th>Offer</th><th>Model</th><th>Tồn thực tế</th><th>Đang giữ</th><th>Khả dụng</th><th>Cảnh báo</th><th>Điều chỉnh</th></tr></thead><tbody>'+rows.map(o=>{const reserved=reservedFor(o.id),available=Math.max(0,o.stock-reserved),m=model(o.modelId);return '<tr '+(selected===o.id?'style="background:var(--color-cobalt-soft)"':'')+'><td><strong>'+esc(o.id)+'</strong></td><td>'+esc(m.name)+'</td><td>'+o.stock+'</td><td>'+reserved+'</td><td><strong>'+available+'</strong></td><td>'+(available<=2?badge('Tồn thấp'):badge('Khả dụng'))+'</td><td><form class="shop-inline-form" data-form="stock" data-id="'+esc(o.id)+'"><label class="field"><span class="sr-only">Tồn mới</span><input name="stock" type="number" min="'+reserved+'" value="'+o.stock+'" required></label><button class="btn btn--secondary">Lưu</button></form></td></tr>';}).join('')+'</tbody></table></div>','Kho');
}

function requestScore(r){let score=0;const reasons=[];if(r.region===shopInfo.region){score+=2;reasons.push('cùng khu vực');}if(r.assembly&&shopInfo.assembly){score+=2;reasons.push('cần lắp ráp');}if(r.budget>=15000000){score++;reasons.push('ngân sách phù hợp full build');}return {score,label:score>=4?'Phù hợp cao':score>=2?'Có thể đáp ứng':'Cần xem kỹ',reasons};}
function buildRequestsPage(){
 const budget=Number(qs.get('budget')||0),region=qs.get('region')||'',assembly=qs.get('assembly')||'',q=(qs.get('q')||'').toLowerCase();
 const list=requests().filter(r=>(!budget||r.budget>=budget)&&(!region||r.region===region)&&(!assembly||(assembly==='yes')===!!r.assembly)&&(!q||[r.purpose,r.scope,r.owned].join(' ').toLowerCase().includes(q)));
 shell(head('Yêu cầu Build đang mở','MVP ưu tiên request có cấu trúc + filter cơ bản. Shop tự quyết định nhu cầu phù hợp; không dùng AI matching.','<a class="btn btn--secondary" href="proposal.html">Proposal của shop</a>')+'<form class="shop-toolbar" data-form="request-filter"><label class="field"><span>Tìm mục đích / linh kiện</span><input name="q" value="'+esc(q)+'" placeholder="gaming, GPU, nâng cấp..."></label><label class="field"><span>Ngân sách tối thiểu</span><select name="budget"><option value="0">Tất cả</option><option value="15000000" '+(budget===15000000?'selected':'')+'>Từ 15 triệu</option><option value="20000000" '+(budget===20000000?'selected':'')+'>Từ 20 triệu</option></select></label><label class="field"><span>Khu vực</span><select name="region"><option value="">Tất cả</option>'+Object.entries(regions).filter(([k])=>k!=='OTHER').map(([k,v])=>'<option value="'+k+'" '+(region===k?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label><label class="field"><span>Lắp ráp</span><select name="assembly"><option value="">Tất cả</option><option value="yes" '+(assembly==='yes'?'selected':'')+'>Cần lắp ráp</option><option value="no" '+(assembly==='no'?'selected':'')+'>Không cần</option></select></label><label class="field"><span>Hạn</span><select name="deadline"><option>Còn hiệu lực</option></select></label><button class="btn btn--secondary">Lọc</button></form><div class="shop-list">'+list.map(r=>{const s=requestScore(r),ps=activeForRequest(r);return '<article class="shop-card"><div><div class="cluster">'+badge('Đang nhận')+'<span class="shop-score">'+s.label+' · rule cơ bản</span></div><h2>'+esc(r.purpose)+'</h2><p><strong>'+money(r.budget)+'</strong> · '+esc(regions[r.region])+' · Hạn '+esc(r.deadline)+'</p><p>Phạm vi: '+esc(r.scope)+'</p><div class="shop-card__meta"><span>'+esc(s.reasons.join(' · ')||'Cần đọc chi tiết')+'</span><span>'+ps.length+' proposal của BuildPro cho version này</span></div></div><a class="btn btn--primary" href="'+link('build-request-detail',{id:r.id})+'">Xem yêu cầu</a></article>';}).join('')+'</div>','Yêu cầu Build');
}

function messageBox(requestId){const msgs=db().shopMeta.messages[requestId]||[];return '<section class="panel shop-chat"><div class="panel__head" style="padding:var(--space-4);margin:0"><div><h2 style="font-size:var(--text-xl)">Trao đổi với người mua</h2><p>Chat nằm trong ngữ cảnh request/proposal, không phải màn hình riêng.</p></div></div><div class="shop-chat__messages">'+msgs.map(m=>'<div class="shop-message '+(m.role==='shop'?'shop-message--shop':'')+'"><strong>'+esc(m.author)+'</strong>'+esc(m.text)+'<small>'+fmtDate(m.at)+'</small></div>').join('')+'</div><form data-form="chat" data-request="'+esc(requestId)+'"><label class="field"><span>Tin nhắn</span><textarea name="text" required maxlength="500" placeholder="Hỏi thêm nhu cầu hoặc giải thích thay đổi proposal..."></textarea></label><button class="btn btn--primary">Gửi</button></form></section>'}
function requestDetailPage(){
 const r=db().requests.find(x=>x.id===(qs.get('id')||'BR-260916-018'));
 if(!r){shell(head('Không tìm thấy yêu cầu','Request không tồn tại trong dữ liệu demo.'),'Chi tiết yêu cầu');return;}
 const existing=activeForRequest(r).find(p=>p.shopId===SHOP_ID);
 shell(head(r.purpose,r.id+' · version '+r.version+' · '+buyerName(r),'<a class="btn btn--secondary" href="build-requests.html">Danh sách</a><a class="btn btn--primary" href="'+link('proposal-builder',{request:r.id,from:existing?.id||''})+'">'+(existing?'Tạo bản chỉnh sửa':'Tạo proposal')+'</a>')+'<div class="shop-grid"><div class="stack">'+panel('Thông tin nhu cầu','<div class="shop-detail-list"><div><span>Ngân sách</span><strong>'+money(r.budget)+'</strong></div><div><span>Khu vực</span><strong>'+esc(regions[r.region])+'</strong></div><div><span>Phạm vi mua</span><strong>'+esc(r.scope)+'</strong></div><div><span>Linh kiện đang có</span><strong>'+esc(r.owned||'Không')+'</strong></div><div><span>Lắp ráp</span><strong>'+(r.assembly?'Có':'Không')+'</strong></div><div><span>Hạn nhận</span><strong>'+esc(r.deadline)+'</strong></div></div>')+panel('Đánh giá trước khi tốn công tư vấn','<p><strong>'+requestScore(r).label+'</strong> theo rule hiển thị minh bạch.</p><p>'+esc(requestScore(r).reasons.join(', ')||'Không có tín hiệu đặc biệt')+'. Đây chỉ là filter/rule MVP, không phải điểm AI.</p><p class="shop-mini">Shop chỉ thấy nhu cầu và khu vực ở giai đoạn này; thông tin giao chi tiết chỉ cần khi phát sinh đơn.</p>')+(existing?panel('Proposal hiện tại','<p>'+esc(existing.id)+' · v'+existing.version+' · '+badge(existing.status)+'</p><p>Tổng '+money(proposalTotal(existing))+' · hết hiệu lực '+fmtDate(existing.expires)+'</p><a class="btn btn--secondary" href="'+link('proposal',{id:existing.id})+'">Mở proposal</a>'):'')+'</div>'+messageBox(r.id)+'</div>','Chi tiết yêu cầu');
}

const defaultMids={CPU:'CPU-12400',MB:'MB-B660',RAM:'RAM-C16',GPU:'GPU-4060',SSD:'SSD-MP44',PSU:'PSU-550',CASE:'CASE-AIR',COOL:''};
function offerOptions(category,selected=''){return '<option value="">'+(category==='COOL'?'Không mua tản rời':'Chọn offer')+'</option>'+bpOffers().filter(o=>o.active&&model(o.modelId).category===category).map(o=>'<option value="'+esc(o.id)+'" '+(selected===o.id?'selected':'')+'>'+esc(model(o.modelId).name)+' · '+money(o.price)+' · tồn '+o.stock+'</option>').join('');}
function builderSelection(form=document.querySelector('[data-form=proposal-builder]')){if(!form)return {};const slots={};for(const c of Object.keys(categories)){const id=form.elements['slot-'+c]?.value;if(id)slots[c]={offerId:id,qty:1};}return slots;}
function proposalPreview(){
 const form=document.querySelector('[data-form=proposal-builder]');if(!form)return;const slots=builderSelection(form),items=Object.values(slots).map(x=>currentOffer(x.offerId)),fee=Number(form.elements.fee.value||0),assembly=Number(form.elements.assembly.value||0),total=items.reduce((s,o)=>s+o.price,0)+fee+assembly,r=db().requests.find(x=>x.id===form.dataset.request),diff=total-(r?.budget||0);const target=document.querySelector('[data-proposal-preview]');if(!target)return;const checks=compatibility({slots});target.innerHTML='<span class="metric-label">Tổng proposal</span><strong class="price">'+money(total)+'</strong><p>Chênh ngân sách: <strong>'+money(diff)+'</strong></p><p>'+(diff<=0?'Trong ngân sách.':'Đang vượt ngân sách; cần giải thích rõ cho khách.')+'</p><ul class="shop-compat">'+checks.map(c=>'<li>'+badge(c.state)+'<div><strong>'+esc(c.title)+'</strong><p>'+esc(c.reason)+'</p></div></li>').join('')+'</ul>';
}
function proposalBuilderPage(){
 const r=db().requests.find(x=>x.id===(qs.get('request')||'BR-260924-021'))||requests()[0],from=proposals().find(p=>p.id===qs.get('from'));
 if(!r){shell(head('Chưa có Build Request','Cần một yêu cầu đang mở trước khi tạo proposal.'),'Tạo Proposal');return;}
 const selected={...defaultMids};if(from)for(const i of from.items)selected[model(currentOffer(i.offerId).modelId).category]=i.offerId;else for(const [c,mid] of Object.entries(defaultMids))selected[c]=mid?SHOP_ID+'-'+mid:'';
 shell(head(from?'Tạo phiên bản chỉnh sửa':'Tạo Proposal',r.id+' · '+r.purpose+' · ngân sách '+money(r.budget),'<a class="btn btn--secondary" href="'+link('build-request-detail',{id:r.id})+'">Về yêu cầu</a>')+'<form data-form="proposal-builder" data-request="'+esc(r.id)+'" data-from="'+esc(from?.id||'')+'"><div class="shop-grid"><section class="shop-slot-grid">'+Object.entries(categories).map(([c,label])=>'<div class="shop-slot"><div><span class="shop-slot__code">'+c+'</span><small>'+esc(label)+'</small></div><label class="field"><span>Offer của BuildPro</span><select name="slot-'+c+'" '+(c==='COOL'?'':'required')+'>'+offerOptions(c,selected[c])+'</select></label><div class="shop-mini">Proposal chỉ dùng offer của shop.</div></div>').join('')+'</section><aside class="stack shop-summary">'+panel('Chi phí và điều kiện','<div data-proposal-preview></div><label class="field"><span>Phí giao dự kiến</span><input name="fee" type="number" min="0" step="1000" value="'+(from?.fee??65000)+'"></label><label class="field"><span>Phí lắp ráp</span><input name="assembly" type="number" min="0" step="1000" value="'+(from?.assembly??(r.assembly?150000:0))+'"></label><label class="field"><span>Hiệu lực (giờ)</span><input name="hours" type="number" min="1" max="72" value="24" required></label><label class="field"><span>Lý do / ghi chú</span><textarea name="note" maxlength="500">Cấu hình cân đối theo ngân sách, ưu tiên linh kiện đang có tồn tại shop.</textarea></label><button class="btn btn--primary" type="submit">'+(from?'Gửi phiên bản mới':'Gửi proposal')+'</button><p class="shop-mini">Giá/tồn sẽ được kiểm tra lại khi khách đặt hàng; gửi proposal không giữ tồn.</p>')+'</aside></div></form>','Tạo Proposal');
 setTimeout(proposalPreview,0);
}

function proposalDetailPage(){
 let p=proposals().find(x=>x.id===qs.get('id'));if(!p)p=proposals().slice().sort((a,b)=>b.version-a.version)[0];
 if(!p){shell(head('Chưa có Proposal','Tạo proposal từ Build Request để xem tại đây.','<a class="btn btn--primary" href="proposal-builder.html">Tạo proposal</a>'),'Proposal');return;}
 const r=db().requests.find(x=>x.id===p.requestId),history=proposals().filter(x=>x.requestId===p.requestId).sort((a,b)=>a.version-b.version),feedback=p.feedback?.at(-1);
 shell(head('Proposal '+p.id,r?.purpose||p.requestId,'<a class="btn btn--secondary" href="'+link('build-request-detail',{id:p.requestId})+'">Mở request</a><a class="btn btn--primary" href="'+link('proposal-builder',{request:p.requestId,from:p.id})+'">Chỉnh sửa thành version mới</a>')+'<div class="shop-grid"><div class="stack">'+panel('Báo giá đã gửi','<div class="cluster">'+badge(p.status)+'<span class="status">Version '+p.version+'</span><span class="status">Hạn '+fmtDate(p.expires)+'</span></div><div class="shop-section">'+p.items.map(i=>{const o=currentOffer(i.offerId),m=model(o.modelId);return '<div class="list-row"><div><strong>'+esc(m.name)+'</strong><p>'+esc(i.offerId)+' · '+money(i.price)+' · BH '+i.warranty+' tháng</p></div><strong>'+money(i.price*i.qty)+'</strong></div>';}).join('')+'</div><p>Giao '+money(p.fee)+' · Lắp '+money(p.assembly)+' · <strong>Tổng '+money(proposalTotal(p))+'</strong></p><p>Chênh ngân sách '+money(proposalTotal(p)-(r?.budget||0))+'.</p><div class="alert alert--info"><i class="alert__signal"></i><div><strong>Proposal có version và hạn hiệu lực</strong><p>Không sửa âm thầm bản khách đã xem. Giá/tồn được recheck trước đặt hàng.</p></div></div>')+(feedback?panel('Yêu cầu chỉnh sửa của khách','<p>'+esc(feedback.text)+'</p><p class="shop-mini">'+(feedback.at?fmtDate(feedback.at):'')+'</p>'):'')+panel('Lịch sử phiên bản',history.map(x=>'<p><a href="'+link('proposal',{id:x.id})+'">Version '+x.version+'</a> · '+money(proposalTotal(x))+' · '+esc(x.status)+'</p>').join(''))+'</div>'+messageBox(p.requestId)+'</div>','Proposal');
}

function orderPage(){
 const all=suborders(),selectedId=qs.get('sub')||all[0]?.sub.id,entry=all.find(x=>x.sub.id===selectedId)||all[0];
 if(!entry){shell(head('Chưa có đơn hàng','Đơn con của BuildPro sẽ xuất hiện sau checkout.'),'Đơn hàng');return;}
 const {order:o,sub:s}=entry;
 shell(head('Quản lý đơn hàng',s.id+' · đơn cha '+o.id,'<a class="btn btn--secondary" href="dashboard.html">Dashboard</a>'+(s.status==='Chờ shop xác nhận'?btn('Từ chối','order-reject',s.id)+btn('Xác nhận đơn','order-confirm',s.id,'primary'):'<a class="btn btn--primary" href="'+link('fulfillment',{sub:s.id})+'">Xử lý giao hàng</a>'))+'<div class="shop-grid"><aside class="panel panel--padded"><h2 style="font-size:var(--text-xl)">Đơn của shop</h2><div class="shop-order-list">'+all.map(({order,sub})=>'<a class="shop-order-link" '+(sub.id===s.id?'aria-current="page"':'')+' href="'+link('order',{sub:sub.id})+'"><strong>'+esc(sub.id)+'</strong><small>'+esc(sub.status)+' · '+money(sub.total)+'</small></a>').join('')+'</div></aside><div class="stack">'+panel('Trạng thái đơn','<div class="cluster">'+badge(o.payment==='paid'?'Thanh toán đã xác minh':o.payment)+badge(s.status)+badge('Giao: '+s.shippingStatus)+'</div><p class="shop-mini">Shop chỉ xem đơn con của mình; payment, order và shipment là các trạng thái tách biệt.</p>')+panel('Sản phẩm cần chuẩn bị',s.items.map(i=>'<div class="list-row"><div><strong>'+esc(i.name)+'</strong><p>'+esc(i.offerId)+' · SL '+i.qty+' · BH '+i.warranty+' tháng</p></div><strong>'+money(i.price*i.qty)+'</strong></div>').join('')+'<p>Tiền hàng '+money(s.subtotal)+' − giảm '+money(s.discount)+' + giao '+money(s.fee)+' = <strong>'+money(s.total)+'</strong></p>')+panel('Thông tin giao cần thiết','<p><strong>'+esc(o.address.name)+'</strong> · '+esc(o.address.phone)+'</p><p>'+esc(o.address.detail)+' · '+esc(regions[o.address.region])+'</p>')+panel('Dòng thời gian','<ul>'+s.timeline.map(t=>'<li>'+fmtDate(t.at)+' · '+esc(t.text)+'</li>').join('')+'</ul>')+'</div></div>','Đơn hàng');
}

function fulfillmentPage(){
 const entry=suborders().find(x=>x.sub.id===(qs.get('sub')||suborders().find(x=>x.sub.status!=='Chờ shop xác nhận')?.sub.id||suborders()[0]?.sub.id));
 if(!entry){shell(head('Chưa có đơn để giao','Xác nhận đơn trước khi vào fulfillment.'),'Giao hàng');return;}const {order:o,sub:s}=entry;const meta=db().shopMeta.packing[s.id]||{};
 const stage=s.shippingStatus==='Đã giao'?3:s.tracking?2:meta.packed?1:0;
 shell(head('Xử lý giao hàng',s.id+' · '+esc(s.status),'<a class="btn btn--secondary" href="'+link('order',{sub:s.id})+'">Về đơn</a>')+'<div class="shop-flow"><div class="shop-flow__step '+(stage>0?'is-done':'is-current')+'"><strong>1. Serial</strong><small>Ghi nhận theo item</small></div><div class="shop-flow__step '+(stage>1?'is-done':stage===1?'is-current':'')+'"><strong>2. Đóng gói</strong><small>Khối lượng và kích thước</small></div><div class="shop-flow__step '+(stage>2?'is-done':stage===2?'is-current':'')+'"><strong>3. Vận đơn</strong><small>Tracking và lịch lấy</small></div><div class="shop-flow__step '+(stage===3?'is-current':'')+'"><strong>4. Bàn giao</strong><small>Trạng thái carrier</small></div></div><div class="shop-grid shop-section"><div class="stack">'+panel('Serial sản phẩm','<form data-form="serials" data-sub="'+esc(s.id)+'">'+s.items.map((i,n)=>'<label class="field"><span>'+esc(i.name)+'</span><input name="serial-'+n+'" value="'+esc(i.serials?.[0]||i.serial||'')+'" placeholder="SN-'+(n+1)+'" required></label>').join('')+'<button class="btn btn--secondary">Lưu serial</button></form>')+panel('Đóng gói','<form data-form="packing" data-sub="'+esc(s.id)+'"><div class="form-grid"><label class="field"><span>Khối lượng (kg)</span><input name="weight" type="number" min="0.1" step="0.1" value="'+esc(meta.weight||'4.2')+'" required></label><label class="field"><span>Số kiện</span><input name="packages" type="number" min="1" value="'+esc(meta.packages||1)+'" required></label></div><label class="field"><span>Kích thước</span><input name="size" value="'+esc(meta.size||'50 × 40 × 30 cm')+'" required></label><button class="btn btn--secondary">Xác nhận đóng gói</button></form>')+'</div>'+panel('Vận đơn','<p>Địa chỉ snapshot: '+esc(o.address.detail)+' · '+esc(regions[o.address.region])+'</p>'+(s.tracking?'<p><strong>'+esc(s.tracking)+'</strong></p>'+badge(s.shippingStatus)+'<div class="stack" style="margin-top:var(--space-4)">'+btn('Đánh dấu đang giao','shipment-pickup',s.id)+btn('Mô phỏng đã giao','shipment-delivered',s.id,'primary')+'</div>':'<form data-form="shipment" data-sub="'+esc(s.id)+'"><label class="field"><span>Dịch vụ</span><select name="service"><option value="standard">Tiêu chuẩn · 3–5 ngày</option><option value="fast">Nhanh · 2–3 ngày</option></select></label><button class="btn btn--primary">Tạo vận đơn demo</button></form>')+'<p class="shop-mini">Một vận đơn/đơn con trong MVP. Không kết nối carrier thật.</p>')+'</div>','Giao hàng');
}

const renderers={dashboard,offers:offersPage,inventory:inventoryPage,'build-requests':buildRequestsPage,'build-request-detail':requestDetailPage,'proposal-builder':proposalBuilderPage,proposal:proposalDetailPage,order:orderPage,fulfillment:fulfillmentPage};
(renderers[page]||dashboard)();

function rerender(){(renderers[page]||dashboard)();}
function findProposal(id){return proposals().find(p=>p.id===id);}

document.addEventListener('click',e=>{
 const side=e.target.closest('[data-sidebar-toggle]');if(side){const shell=document.querySelector('.shop-shell'),open=shell.classList.toggle('is-sidebar-open');side.setAttribute('aria-expanded',String(open));return;}
 const disabled=e.target.closest('[data-disabled-link]');if(disabled){e.preventDefault();toast('Ngoài scope core của ticket hiện tại.');return;}
 const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;
 try{
  if(act==='offer-toggle'){tx(s=>{const o=currentOffer(id);s.overrides[id]={...s.overrides[id],active:!o.active};});rerender();toast('Đã cập nhật trạng thái tin bán.');}
  if(act==='offer-edit'){const o=currentOffer(id),value=prompt('Giá mới (VND)',String(o.price));if(value===null)return;const price=Number(value);if(!Number.isInteger(price)||price<=0)throw Error('Giá phải là số nguyên dương.');tx(s=>s.overrides[id]={...s.overrides[id],price});rerender();toast('Đã cập nhật giá offer demo.');}
  if(act==='order-confirm'){const entry=suborders().find(x=>x.sub.id===id);if(!entry)throw Error('Không tìm thấy đơn.');tx(()=>{entry.sub.status='Chuẩn bị hàng';entry.sub.timeline.push({at:Date.now(),text:'Shop xác nhận đơn và bắt đầu chuẩn bị hàng'});});rerender();toast('Đã xác nhận đơn.');}
  if(act==='order-reject'){const entry=suborders().find(x=>x.sub.id===id);if(!entry)throw Error('Không tìm thấy đơn.');const reason=prompt('Lý do từ chối','Hết hàng sau đối chiếu tồn');if(!reason)return;tx(()=>{entry.sub.status='Đã hủy';entry.sub.timeline.push({at:Date.now(),text:'Shop từ chối: '+reason});});rerender();toast('Đã ghi nhận từ chối đơn demo.');}
  if(act==='shipment-pickup'){const entry=suborders().find(x=>x.sub.id===id);tx(()=>{entry.sub.status='Đang giao';entry.sub.shippingStatus='Đang giao';entry.sub.timeline.push({at:Date.now(),text:'Carrier đã lấy hàng demo'});});rerender();}
  if(act==='shipment-delivered'){const entry=suborders().find(x=>x.sub.id===id);tx(()=>{entry.sub.status='Hoàn tất';entry.sub.shippingStatus='Đã giao';entry.sub.timeline.push({at:Date.now(),text:'Đã giao thành công demo'});});rerender();}
 }catch(err){toast(err.message);}
});

document.addEventListener('change',e=>{if(e.target.closest('[data-form=proposal-builder]'))proposalPreview();});
document.addEventListener('input',e=>{if(e.target.closest('[data-form=proposal-builder]')&&['fee','assembly'].includes(e.target.name))proposalPreview();});
document.addEventListener('submit',e=>{
 const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;
 const d=Object.fromEntries(new FormData(form));
 try{
  if(form.dataset.form==='offer-filter'||form.dataset.form==='request-filter'){const p=new URLSearchParams();for(const [k,v] of Object.entries(d))if(v)p.set(k,v);location.search=p;return;}
  if(form.dataset.form==='stock'){const id=form.dataset.id,o=currentOffer(id),reserved=reservedFor(id),stock=Number(d.stock);if(!Number.isInteger(stock)||stock<reserved)throw Error('Tồn thực tế không được thấp hơn lượng đang giữ ('+reserved+').');tx(s=>{s.overrides[id]={...s.overrides[id],stock};s.shopMeta.inventoryLog.unshift({offerId:id,stock,at:Date.now()});});rerender();toast('Đã cập nhật tồn kho.');return;}
  if(form.dataset.form==='chat'){const text=String(d.text||'').trim();if(!text)throw Error('Nhập nội dung tin nhắn.');const rid=form.dataset.request;tx(s=>{s.shopMeta.messages[rid]||=[];s.shopMeta.messages[rid].push({author:shopInfo.name,role:'shop',text,at:Date.now()});});rerender();toast('Đã gửi tin nhắn demo.');return;}
  if(form.dataset.form==='proposal-builder'){
   const r=db().requests.find(x=>x.id===form.dataset.request);if(!r||r.status!=='open')throw Error('Yêu cầu không còn nhận proposal.');const slots=builderSelection(form),required=['CPU','MB','RAM','GPU','SSD','PSU','CASE'];if(required.some(c=>!slots[c]))throw Error('Cần chọn đủ các nhóm linh kiện chính.');const checks=compatibility({slots});if(checks.some(c=>c.state==='Không tương thích'))throw Error('Cấu hình đang có lỗi không tương thích; hãy đổi linh kiện trước khi gửi.');const items=Object.values(slots).map(x=>{const o=currentOffer(x.offerId);if(!o.active||o.shopId!==SHOP_ID||o.stock<1)throw Error('Có offer không còn khả dụng.');return {offerId:o.id,qty:1,price:o.price,warranty:o.warranty};});const previous=findProposal(form.dataset.from);const version=previous?previous.version+1:Math.max(0,...proposals().filter(p=>p.requestId===r.id).map(p=>p.version))+1;const p={id:uid('PR'),userId:r.userId,requestId:r.id,requestVersion:r.version,version,shopId:SHOP_ID,status:'Đã gửi',expires:Date.now()+Number(d.hours)*3600000,items,fee:Number(d.fee||0),assembly:Number(d.assembly||0),feedback:[],note:String(d.note||'')};tx(s=>{if(previous)previous.status='Đã thay thế';s.proposals.push(p);});location.href=link('proposal',{id:p.id});return;
  }
  if(form.dataset.form==='serials'){const entry=suborders().find(x=>x.sub.id===form.dataset.sub);tx(()=>entry.sub.items.forEach((i,n)=>{const serial=String(d['serial-'+n]||'').trim();i.serial=serial;i.serials=[serial];}));rerender();toast('Đã lưu serial.');return;}
  if(form.dataset.form==='packing'){const id=form.dataset.sub;tx(s=>{s.shopMeta.packing[id]={weight:Number(d.weight),packages:Number(d.packages),size:d.size,packed:true,at:Date.now()};});rerender();toast('Đã xác nhận đóng gói.');return;}
  if(form.dataset.form==='shipment'){const entry=suborders().find(x=>x.sub.id===form.dataset.sub),meta=db().shopMeta.packing[entry.sub.id];if(!meta?.packed)throw Error('Xác nhận đóng gói trước khi tạo vận đơn.');if(entry.sub.items.some(i=>!i.serials?.length))throw Error('Nhập serial trước khi tạo vận đơn.');tx(()=>{entry.sub.deliveryService=d.service;entry.sub.tracking='PCM-GHN-'+Math.floor(10000+Math.random()*89999);entry.sub.shippingStatus='Chờ lấy hàng';entry.sub.status='Chờ lấy hàng';entry.sub.timeline.push({at:Date.now(),text:'Đã tạo vận đơn '+entry.sub.tracking});});rerender();toast('Đã tạo vận đơn demo.');return;}
 }catch(err){toast(err.message);}
});

document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='shop-global-search'){e.preventDefault();const q=e.target.value.trim();location.href=q.toUpperCase().startsWith('BR-')?link('build-requests',{q}):q.toUpperCase().startsWith('PR-')?link('proposal',{id:q}):q.toUpperCase().startsWith('SUB-')?link('order',{sub:q}):link('offers',{q});}});
